   i.e. x_0 * 1/x_1 * x_2 * 1/x_3 * x_4 ...
   Use OpenMP to compute product in parallel.
   Example:

   input: [4, 2, 10, 4, 5]
   output: 25
*/
double productWithInverses(std::vector<double> const& x) {

```cpp
#include <vector>
#include <omp.h>

double productWithInverses(std::vector<double> const& x) {
    double product = 1.0;

    #pragma omp parallel for reduction(*:product)
    for (std::size_t i = 0; i < x.size(); ++i) {
        if ((i & 1u) == 0u) {
            product *= x[i];
        } else {
            product *= 1.0 / x[i];
        }
    }

    return product;
}
