#include <vector>
#include <omp.h>

double productWithInverses(std::vector<double> const& x) {
    // Compute as ratio of two products to avoid order-dependent divide/multiply interleaving.
    double even_prod = 1.0;
    double odd_prod  = 1.0;

    #pragma omp parallel for reduction(*:even_prod, odd_prod)
    for (long long i = 0; i < static_cast<long long>(x.size()); ++i) {
        if ((i & 1LL) == 0LL) {
            even_prod *= x[static_cast<std::size_t>(i)];
        } else {
            odd_prod *= x[static_cast<std::size_t>(i)];
        }
    }

    return even_prod / odd_prod;
}
